import json

def my_transform(grid):
    """
    1. Find bounding box of all non-bg points
    2. For each row, fill gaps between consecutive non-bg with 2
    3. For each column, fill gaps between consecutive non-bg with 2
    """
    from collections import Counter
    c = Counter(x for r in grid for x in r)
    bg = c.most_common(1)[0][0]

    result = [row[:] for row in grid]

    # Fill horizontal gaps between consecutive non-bg points
    for i, row in enumerate(result):
        positions = [j for j, x in enumerate(row) if x != bg]
        for k in range(len(positions) - 1):
            c1, c2 = positions[k], positions[k+1]
            if c1 != bg and c2 != bg and c2 > c1:
                for j in range(c1 + 1, c2):
                    if result[i][j] == bg:
                        result[i][j] = 2

    # Fill vertical gaps between consecutive non-bg points
    for j in range(len(result[0])):
        positions = [i for i, row in enumerate(result) if row[j] != bg]
        for k in range(len(positions) - 1):
            r1, r2 = positions[k], positions[k+1]
            if r2 > r1:
                for i in range(r1 + 1, r2):
                    if result[i][j] == bg:
                        result[i][j] = 2

    return result

