def my_transform_v6(grid):
    """
    Fill horizontally between adjacent marks in any row that has marks.
    Fill vertically from edge marks of the bbox toward the opposite edge.
    """
    from collections import Counter
    c = Counter(x for r in grid for x in r)
    bg = c.most_common(1)[0][0]

    rows, cols = len(grid), len(grid[0])

    # Find all non-bg positions
    positions = [(i, j) for i, r in enumerate(grid) for j, x in enumerate(r) if x != bg]
    if not positions:
        return grid

    # Find bounding box
    r_min, r_max = min(p[0] for p in positions), max(p[0] for p in positions)
    c_min, c_max = min(p[1] for p in positions), max(p[1] for p in positions)

    result = [row[:] for row in grid]

    # Horizontal fills: between consecutive adjacent marks
    for i in range(r_min, r_max + 1):
        row_positions = [j for j in range(c_min, c_max + 1) if grid[i][j] != bg]
        for k in range(len(row_positions) - 1):
            for j in range(row_positions[k] + 1, row_positions[k+1]):
                if result[i][j] == bg:
                    result[i][j] = 2

    # Vertical fills: from edge marks toward center or opposite edge
    for j in range(c_min, c_max + 1):
        col_positions = [i for i in range(r_min, r_max + 1) if grid[i][j] != bg]
        if col_positions:
            # Check if there's a mark at r_min or r_max in this column
            if col_positions[0] == r_min:
                # Mark at top edge, fill downward to next mark
                for k in range(1, len(col_positions)):
                    if col_positions[k] > col_positions[k-1] + 1:
                        for i in range(col_positions[k-1] + 1, col_positions[k]):
                            if result[i][j] == bg:
                                result[i][j] = 2
            elif col_positions[-1] == r_max:
                # Mark at bottom edge, fill upward to previous mark
                for k in range(len(col_positions) - 2, -1, -1):
                    if col_positions[k] < col_positions[k+1] - 1:
                        for i in range(col_positions[k+1] - 1, col_positions[k], -1):
                            if result[i][j] == bg:
                                result[i][j] = 2

    return result

